import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { InputLabel } from "./input-label";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Form Fields/Input Label",
  component: InputLabel,
  parameters: {
    docs: {
      description: {
        component:
          "Label for a form input. Renders a `<label>` whose `htmlFor` is the `inputName`, followed by an " +
          'optional `additionalText` in parentheses and, when `isRequired` is set, the translated "mandatory" ' +
          'label in parentheses ("Obligatoriskt" in Swedish, rendered lowercase by the stylesheet so it displays as ' +
          '"(obligatoriskt)"). `isGroupedInput` switches the text style from `body-m` to ' +
          "the smaller `p_small`. Any other props are spread onto the `<label>` element. The component is also " +
          "exported from the package index under the alias `LabelForInput`.",
      },
    },
  },
  argTypes: {
    contentfulLabelId: { table: { disable: true } },
    inputName: { table: { disable: true } },
  },
  args: {
    label: "Förnamn",
    inputName: "firstName",
    additionalText: "",
    isRequired: false,
    isGroupedInput: false,
    contentfulLabelId: undefined,
  },
} satisfies Meta<typeof InputLabel>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByText("Förnamn")).toHaveAttribute("for", "firstName");
  },
};

export const VariantStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="label states" variantType="state">
      <Variant label="plain">
        <InputLabel {...args} />
      </Variant>
      <Variant label="additionalText">
        <InputLabel {...args} additionalText="Ticket to Ride (9-64 år)" />
      </Variant>
      <Variant label="isRequired">
        <InputLabel {...args} isRequired />
      </Variant>
      <Variant label="isGroupedInput">
        <InputLabel {...args} isGroupedInput />
      </Variant>
      <Variant label="additionalText + isRequired">
        <InputLabel {...args} additionalText="Ticket to Ride (9-64 år)" isRequired />
      </Variant>
    </ShowcaseLayout>
  ),
};
